-- E-commerce SQLite Database (pre-baked, no UPDATEs needed)
-- Tables: categories, customers, products, orders, order_items,
--         customer_addresses, shipping_methods, shipments
-- Data: 5 categories, 10 customers, 25 products, 2015 orders,
--        6022 order_items, 1916 shipments, 25 addresses, 5 methods

CREATE TABLE categories (
    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
    category_name TEXT NOT NULL,
    description TEXT,
    created_at TEXT DEFAULT CURRENT_TEXT
);



CREATE TABLE customers (
    customer_id INTEGER PRIMARY KEY AUTOINCREMENT,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    phone TEXT,
    address TEXT,
    city TEXT,
    state TEXT,
    country TEXT DEFAULT 'USA',
    postal_code TEXT,
    created_at TEXT DEFAULT CURRENT_TEXT
);



CREATE TABLE products (
    product_id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_name TEXT NOT NULL,
    category_id INTEGER REFERENCES categories(category_id),
    description TEXT,
    price REAL NOT NULL,
    stock_quantity INTEGER DEFAULT 0,
    created_at TEXT DEFAULT CURRENT_TEXT,
    updated_at TEXT DEFAULT CURRENT_TEXT
);



CREATE TABLE orders (
    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
    order_date TEXT DEFAULT CURRENT_TEXT,
    status TEXT DEFAULT 'pending',
    total_amount REAL,
    shipping_address TEXT,
    shipping_city TEXT,
    shipping_state TEXT,
    shipping_country TEXT,
    shipping_postal_code TEXT,
    notes TEXT
);











































CREATE TABLE order_items (
    order_item_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id INTEGER NOT NULL REFERENCES orders(order_id),
    product_id INTEGER NOT NULL REFERENCES products(product_id),
    quantity INTEGER NOT NULL,
    unit_price REAL NOT NULL,
    subtotal REAL NOT NULL
);



























































































































CREATE TABLE customer_addresses (
    address_id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id INTEGER NOT NULL,
    address_type TEXT NOT NULL,
    full_name TEXT NOT NULL,
    phone_number TEXT,
    address_line1 TEXT NOT NULL,
    address_line2 TEXT,
    city TEXT NOT NULL,
    state_province TEXT,
    postal_code TEXT,
    country_code TEXT NOT NULL,
    is_default INTEGER NOT NULL DEFAULT FALSE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TEXT,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TEXT,
    CONSTRAINT fk_customer_addresses_customer
        FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);



CREATE TABLE shipping_methods (
    shipping_method_id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    base_cost REAL,
    is_active INTEGER NOT NULL DEFAULT TRUE
);



CREATE TABLE shipments (
    shipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_id INTEGER NOT NULL,
    shipping_method_id INTEGER NOT NULL,
    shipping_address_id INTEGER NOT NULL,
    carrier_name TEXT,
    tracking_number TEXT,
    shipment_status TEXT NOT NULL DEFAULT 'created',
    shipped_at TEXT,
    delivered_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TEXT,
    CONSTRAINT fk_shipments_order
        FOREIGN KEY (order_id) REFERENCES orders(order_id),
    CONSTRAINT fk_shipments_method
        FOREIGN KEY (shipping_method_id) REFERENCES shipping_methods(shipping_method_id),
    CONSTRAINT fk_shipments_address
        FOREIGN KEY (shipping_address_id) REFERENCES customer_addresses(address_id)
);








































